// Modified by kbn-proto-ui: removed the deprecated AI Assistant logo mapping.

import React from 'react';
import { EuiButton, EuiButtonEmpty, EuiButtonIcon, EuiToolTip } from '@elastic/eui';

import {
  useAiButtonGradientStyles,
  useSvgAiGradient,
} from '../gradient_styles/use_ai_gradient_styles';
import { useAiButtonXsSizeCss } from './ai_button_xs_size_styles';
import { SvgAiGradientDefs } from '../gradient_styles/svg_ai_gradient_defs';
import type { AiButtonIconType, AiButtonProps, AiButtonVariant } from './types';
import { ADD_TO_CHAT_LABEL } from './constants';

const usesAddToChatLabel = (iconType?: AiButtonIconType): boolean => iconType === 'addToChat';

const resolveButtonLabel = (
  iconType: AiButtonIconType | undefined,
  children: React.ReactNode
): React.ReactNode => (usesAddToChatLabel(iconType) ? ADD_TO_CHAT_LABEL : children);

const resolveIconOnlyTooltipContent = ({
  iconType,
  ariaLabel,
  toolTipContent,
}: {
  iconType: AiButtonIconType;
  ariaLabel: string;
  toolTipContent?: React.ReactNode;
}): React.ReactNode => {
  if (usesAddToChatLabel(iconType)) {
    return ADD_TO_CHAT_LABEL;
  }

  if (toolTipContent != null) {
    return toolTipContent;
  }

  return ariaLabel;
};

// Per design: only xs uses small icon; s and m both use medium icon.
const getSyncedIconSize = (size?: 'xs' | 's' | 'm') => (size === 'xs' ? 's' : 'm');

/** Button-only HTML attributes to omit when rendering as anchor. */
const BUTTON_ONLY_KEYS = [
  'form',
  'formAction',
  'formEncType',
  'formMethod',
  'formNoValidate',
  'formTarget',
  'name',
  'type',
  'value',
] as const;
/** Anchor-only HTML attributes to omit when rendering as button. */
const ANCHOR_ONLY_KEYS = ['href', 'target', 'rel', 'download', 'referrerPolicy', 'ping'] as const;

/**
 * Keep only the props branch that matches `hasHref`, so spreads satisfy EUI's union.
 */
function filterForButtonOrAnchor(
  rest: Record<string, unknown>,
  hasHref: boolean
): Record<string, unknown> {
  const filtered = { ...rest };
  for (const k of hasHref ? BUTTON_ONLY_KEYS : ANCHOR_ONLY_KEYS) {
    delete filtered[k];
  }
  return filtered;
}

export const AiButtonBase = (props: AiButtonProps) => {
  const variant: AiButtonVariant = props.variant ?? 'base';

  const euiButtonXsSizeCss = useAiButtonXsSizeCss();
  const { buttonCss, labelCss } = useAiButtonGradientStyles({
    variant,
    iconOnly: props.iconOnly,
  });
  const { gradientId, iconGradientCss, colors } = useSvgAiGradient({ variant });

  const svgGradientDefs = iconGradientCss ? (
    <SvgAiGradientDefs gradientId={gradientId} colors={colors} />
  ) : null;

  if (props.iconOnly === true) {
    const {
      iconType,
      css: userCss,
      display: _display,
      iconOnly: _iconOnly,
      variant: _variant,
      withToolTip,
      toolTipContent,
      'aria-label': ariaLabel,
      ...rest
    } = props;

    const filtered = filterForButtonOrAnchor(rest, !!rest.href);
    const iconProps = {
      ...filtered,
      'aria-label': ariaLabel,
      iconType,
      iconSize: rest.iconSize ?? getSyncedIconSize(rest.size),
      css: [buttonCss, iconGradientCss, userCss],
    };

    const iconButton = <EuiButtonIcon {...iconProps} />;

    return (
      <>
        {svgGradientDefs}
        {withToolTip === true ? (
          <EuiToolTip
            content={resolveIconOnlyTooltipContent({ iconType, ariaLabel, toolTipContent })}
          >
            {iconButton}
          </EuiToolTip>
        ) : (
          iconButton
        )}
      </>
    );
  }

  if (props.variant === 'empty' || props.variant === 'outlined') {
    const {
      variant: _variant,
      iconOnly: _iconOnly,
      children,
      css: userCss,
      iconType,
      textProps,
      ...rest
    } = props;

    const filtered = filterForButtonOrAnchor(rest, !!rest.href);
    const emptyProps = {
      ...filtered,
      iconSize: rest.iconSize ?? getSyncedIconSize(rest.size),
      iconType,
      css: [buttonCss, iconGradientCss, userCss],
      // Apply label styles on EUI's text span so padding is not doubled and truncation still works.
      textProps: {
        ...textProps,
        css: [labelCss, textProps !== false ? textProps?.css : undefined],
      },
      children: resolveButtonLabel(iconType, children),
    };
    return (
      <>
        {svgGradientDefs}
        <EuiButtonEmpty {...emptyProps} />
      </>
    );
  }

  const {
    variant: _variant,
    iconOnly: _iconOnly,
    children,
    css: userCss,
    iconType,
    size,
    ...rest
  } = props;
  const buttonSize: 's' | 'm' | undefined = size === 'xs' ? 's' : size;

  const filtered = filterForButtonOrAnchor(rest, !!rest.href);
  const buttonProps = {
    ...filtered,
    size: buttonSize,
    iconSize: rest.iconSize ?? getSyncedIconSize(size),
    iconType,
    css: [buttonCss, iconGradientCss, size === 'xs' && euiButtonXsSizeCss, userCss],
    fill: variant === 'accent',
    children: <span css={labelCss}>{resolveButtonLabel(iconType, children)}</span>,
  };

  return (
    <>
      {svgGradientDefs}
      <EuiButton {...buttonProps} />
    </>
  );
};
